import { Component, inject } from '@angular/core';
import { NonNullableFormBuilder, ReactiveFormsModule } from '@angular/forms';

@Component({
  selector: 'app-edit-employee',
  imports: [ReactiveFormsModule],
  templateUrl: './edit-employee.html',
})
export class EditEmployee {
  private readonly api = inject(EmployeeApi);
  private readonly fb = inject(NonNullableFormBuilder);
  readonly form = this.fb.group({
    name: '',
    email: { value: '', disabled: true },
  });

  save() {
    // The cast hides Partial: the PUT body has no email
    this.api.update(this.form.value as Employee).subscribe();
  }
}

import { Component, inject } from '@angular/core';
import { NonNullableFormBuilder, ReactiveFormsModule } from '@angular/forms';

@Component({
  selector: 'app-edit-employee',
  imports: [ReactiveFormsModule],
  templateUrl: './edit-employee.html',
})
export class EditEmployee {
  private readonly api = inject(EmployeeApi);
  private readonly fb = inject(NonNullableFormBuilder);
  readonly form = this.fb.group({
    name: '',
    email: { value: '', disabled: true },
  });

  save() {
    // { name: string; email: string }, disabled controls included
    const employee: Employee = this.form.getRawValue();
    this.api.update(employee).subscribe();
  }
}

